// Normaliza el body del webhook al contrato de entrada esperado.
// Contrato esperado (todo excepto `brief` es opcional; lo que falte se marca pendiente):
// {
//   brief: string (obligatorio, pedido en lenguaje natural),
//   cliente: { nombre, slug },
//   marca: { tono, voz, visual: { paleta: [], tipografia, estilo }, claims_aprobados: [] },
//   estrategia: { pilares_contenido: [], oferta, etapa_funnel }
// }

const body = $json.body || $json;

if (!body.brief || typeof body.brief !== 'string' || !body.brief.trim()) {
  throw new Error('Falta "brief" en el body del webhook: el pedido en lenguaje natural es obligatorio.');
}

const marca = body.marca || {};
const visual = marca.visual || {};
const estrategia = body.estrategia || {};
const cliente = body.cliente || {};

const camposFaltantes = [];
if (!marca.tono) camposFaltantes.push('marca.tono');
if (!visual.paleta || !visual.paleta.length) camposFaltantes.push('marca.visual.paleta');
if (!visual.tipografia) camposFaltantes.push('marca.visual.tipografia');
if (!marca.claims_aprobados || !marca.claims_aprobados.length) camposFaltantes.push('marca.claims_aprobados');

return {
  brief: body.brief.trim(),
  cliente: {
    nombre: cliente.nombre || null,
    slug: cliente.slug || null,
  },
  marca: {
    tono: marca.tono || null,
    voz: marca.voz || null,
    visual: {
      paleta: visual.paleta || [],
      tipografia: visual.tipografia || null,
      estilo: visual.estilo || null,
    },
    claims_aprobados: marca.claims_aprobados || [],
  },
  estrategia: {
    pilares_contenido: estrategia.pilares_contenido || [],
    oferta: estrategia.oferta || null,
    etapa_funnel: estrategia.etapa_funnel || null,
  },
  campos_faltantes_input: camposFaltantes,
};

const SYSTEM_PROMPT = "Eres el especialista en motion / Reels de un sistema de generacion de contenido para redes sociales multi-cliente. Tu unica responsabilidad es convertir un brief y el contexto de marca que recibes en el mensaje del usuario en:\n\n1. Un guion + shot list en Markdown, listo para revision humana.\n2. Un storyboard animado por escenas en HTML/CSS autocontenido (formato vertical 9:16, sin dependencias externas, animado con @keyframes) que sirva de previsualizacion de ritmo y movimiento, no un video final.\n\nNo generas video renderizado ni publicas nada: el resultado es solo para revision humana antes de produccion.\n\nReglas:\n- Nunca inventes tono, paleta, tipografia o claims de marca que no esten en el contexto recibido. Si falta algun dato de marca necesario, declaralo en el campo `pendientes` de tu respuesta en vez de inventarlo.\n- El guion debe incluir: Hook (primeros 1-2s, la razon para no hacer scroll), escenas numeradas (descripcion visual, texto en pantalla, voz en off/copy, duracion aproximada), ritmo/pacing (cortes por segundo, transicion sugerida entre escenas), CTA final alineado a la etapa de funnel indicada (si se indica en el contexto), mood de musica/SFX sugerido (no un archivo concreto).\n- Cada escena del guion debe tener tambien su HTML de previsualizacion correspondiente en el array `escenas`: un documento HTML autocontenido (CSS embebido en un <style>, sin dependencias externas ni CDNs) con un contenedor de aspect-ratio 9:16 que anime la composicion aproximada de esa escena con @keyframes/transiciones - suficiente para transmitir timing y movimiento, no un diseno final de arte.\n- Usa la paleta/tipografia de marca recibida en el contexto si esta disponible; si no esta disponible, usa una paleta neutra de marcador de posicion y declaralo en `pendientes`.\n- En `fuentes`, cita explicitamente que parte del contexto recibido (brand kit, estrategia, brief de cliente) respalda el tono y los claims usados.\n- Responde siempre usando la tool `deliver_reel_storyboard` - nunca respondas en texto plano fuera de la tool.";

// Arma el mensaje de usuario para Claude a partir del input normalizado,
// y arma el request completo (incluyendo tool-use forzado) para el nodo HTTP Request.

const d = $json;

const contextoLines = [];
contextoLines.push(`Cliente: ${d.cliente.nombre || 'no especificado'}`);
if (d.marca.tono) contextoLines.push(`Tono de marca: ${d.marca.tono}`);
if (d.marca.visual.paleta && d.marca.visual.paleta.length) contextoLines.push(`Paleta: ${d.marca.visual.paleta.join(', ')}`);
if (d.marca.visual.tipografia) contextoLines.push(`Tipografia: ${d.marca.visual.tipografia}`);
if (d.marca.visual.estilo) contextoLines.push(`Estilo visual: ${d.marca.visual.estilo}`);
if (d.marca.claims_aprobados && d.marca.claims_aprobados.length) contextoLines.push(`Claims aprobados: ${d.marca.claims_aprobados.join(' | ')}`);
if (d.estrategia.pilares_contenido && d.estrategia.pilares_contenido.length) contextoLines.push(`Pilares de contenido: ${d.estrategia.pilares_contenido.join(', ')}`);
if (d.estrategia.oferta) contextoLines.push(`Oferta vigente: ${d.estrategia.oferta}`);
if (d.estrategia.etapa_funnel) contextoLines.push(`Etapa de funnel objetivo: ${d.estrategia.etapa_funnel}`);
if (d.campos_faltantes_input.length) contextoLines.push(`Campos de marca NO provistos (tratalos como pendiente, no los inventes): ${d.campos_faltantes_input.join(', ')}`);

const userMessage = `Pedido del usuario:\n${d.brief}\n\nContexto de marca/cliente disponible:\n${contextoLines.join('\n')}`;

const tool = {
  name: 'deliver_reel_storyboard',
  description: 'Entrega el guion en Markdown y el storyboard animado por escenas de un Reel.',
  input_schema: {
    type: 'object',
    properties: {
      guion_markdown: {
        type: 'string',
        description: 'Guion completo en Markdown: Hook, escenas numeradas, ritmo/pacing, CTA final, musica/SFX, fuentes.',
      },
      escenas: {
        type: 'array',
        description: 'Una entrada por cada escena numerada del guion.',
        items: {
          type: 'object',
          properties: {
            numero: { type: 'integer' },
            titulo: { type: 'string' },
            html: {
              type: 'string',
              description: 'HTML autocontenido 9:16, CSS embebido en <style>, animado con @keyframes, sin dependencias externas.',
            },
          },
          required: ['numero', 'html'],
        },
      },
      pendientes: {
        type: 'array',
        items: { type: 'string' },
        description: 'Datos de marca que faltaron y se marcaron como pendientes en vez de inventarse. Array vacio si no hay ninguno.',
      },
      fuentes: {
        type: 'array',
        items: { type: 'string' },
        description: 'Que parte del contexto recibido respalda el tono/claims usados.',
      },
    },
    required: ['guion_markdown', 'escenas', 'pendientes', 'fuentes'],
  },
};

const claude_request = {
  model: 'claude-sonnet-4-5',
  max_tokens: 8000,
  system: SYSTEM_PROMPT,
  messages: [
    { role: 'user', content: userMessage },
  ],
  tools: [tool],
  tool_choice: { type: 'tool', name: 'deliver_reel_storyboard' },
};

return { claude_request, cliente: d.cliente, brief: d.brief };

// Extrae el bloque tool_use de la respuesta de la API de Claude y arma la respuesta final del webhook.

const response = $json;
const cliente = $('Construir Prompt').first().json.cliente;
const brief = $('Construir Prompt').first().json.brief;

if (response.type === 'error') {
  return {
    ok: false,
    error: response.error && response.error.message ? response.error.message : 'Error desconocido llamando a la API de Claude.',
  };
}

const toolUseBlock = (response.content || []).find(
  (block) => block.type === 'tool_use' && block.name === 'deliver_reel_storyboard'
);

if (!toolUseBlock) {
  return {
    ok: false,
    error: 'Claude no devolvio el resultado estructurado esperado (tool_use "deliver_reel_storyboard"). stop_reason: ' + response.stop_reason,
  };
}

const result = toolUseBlock.input;

return {
  ok: true,
  cliente,
  brief,
  guion_markdown: result.guion_markdown,
  escenas: result.escenas,
  pendientes: result.pendientes || [],
  fuentes: result.fuentes || [],
};
